package android.content;
import java.util.*;
public class SharedPreferences {
 private final Map<String,Object> values=new HashMap<>();
 public String getString(String k,String d){return (String)values.getOrDefault(k,d);}
 public long getLong(String k,long d){return (Long)values.getOrDefault(k,d);}
 public int getInt(String k,int d){return (Integer)values.getOrDefault(k,d);}
 public boolean getBoolean(String k,boolean d){return (Boolean)values.getOrDefault(k,d);}
 public Editor edit(){return new Editor();}
 public class Editor {private final Map<String,Object> edits=new HashMap<>();private boolean clear;
  public Editor putString(String k,String v){edits.put(k,v);return this;}
  public Editor putLong(String k,long v){edits.put(k,v);return this;}
  public Editor putInt(String k,int v){edits.put(k,v);return this;}
  public Editor putBoolean(String k,boolean v){edits.put(k,v);return this;}
  public Editor remove(String k){edits.put(k,null);return this;}
  public Editor clear(){clear=true;return this;}
  public boolean commit(){if(clear)values.clear();for(Map.Entry<String,Object> e:edits.entrySet())if(e.getValue()==null)values.remove(e.getKey());else values.put(e.getKey(),e.getValue());return true;}
  public void apply(){commit();}
 }
}
